def caption(filename,text):
 global s
 lines=s.splitlines();found=False
 for i,line in enumerate(lines):
  if line.startswith(('\\figpanel{'+filename+'}','\\widepanel{'+filename+'}')):
   label=re.findall(r'\{(fig:[^}]+)\}',line)[-1];cmd='figpanel' if line.startswith('\\figpanel') else 'widepanel';lines[i]='\\'+cmd+'{'+filename+'}{'+text+'}{'+label+'}'+('{}' if cmd=='figpanel' else '');found=True
 assert found,filename
 s='\n'.join(lines)+'\n'
caption('fig01_architecture_user.pdf',r'\textbf{AbDev-X framework and expert architectures.} \textbf{A}, the author-edited overview: paired VH/VL sequences supply frozen ESM-2 and AbLang2 representations and 165 sequence descriptors; HC/LC subtype is metadata. ABodyBuilder3 supplies predicted-Fv context for the last, structure-informed bio block (57 features), which merges precomputed TAP, MOE, Aggrescan3D, and AntiFold quantities and includes some sequence summaries. Five operational blocks feed four experts. Six property groups summarize ten distinct assay outputs; five endpoints use code-default masks and eligibility. \textbf{B}, E1 evaluates five source heads by inner OOF score, selects a source, refits, and produces the connected prediction. \textbf{C}, A-MGFS applies keyword masks, scaling, optional PCA, and ridge regression. \textbf{D}, D-Stack combines PLM and descriptor/bio predictions through an OOF ridge meta-head. \textbf{E}, F-MoE mixes assay-eligible group predictors using fixed CV-softmax weights; HAC is the illustrated group set. The primary final prediction is the sum of the four expert outputs divided by four. Shared heads use training-fitted standardization, 90\%-variance PCA when the feature count exceeds 100, and RidgeCV. Intact IgG is illustrative (PDB 1IGT); the Fv and sequence excerpts use the example antibody.')
caption('main07_baseline_context.pdf',r'\textbf{Local benchmark performance and verified published comparison context.} \textbf{A}, primary-code cluster--isotype CV means $\pm$ fold SD and best stored local entries; stars indicate larger point estimates, not statistical significance. \textbf{B}, AbDev-X GDPa3 BCa 95\% intervals, the largest of Jiang\,et\,al.\!\textquotesingle s three published assay-level point estimates, stored DELPHI configuration scores, and published competition-champion diamonds~\citep{jiang2026,ginkgo2026}. Jiang values are from Supporting Table S3; mapped titer is a Table S4 sensitivity endpoint, not a directly matched result. The published best point may come from a different Jiang model for each assay. Literature prediction records and paired uncertainty are unavailable, so no published-comparator error bars or superiority tests are invented. Amini\,et\,al. use internal Biogen panels rather than GDPa3 and are discussed separately~\citep{amini2026}. \textbf{C}, the archival source-stack/GP graphic, transcribed from its vector bars; it is not a primary-model GP experiment. Supplementary Table~\ref{tab:published} reports the full assay-level comparison and protocol scope.')
caption('main04_encoder_structure.pdf',r'\textbf{Encoder screen and structural feature ablation with matched uncertainty.} \textbf{A--B}, dot--whisker comparisons of VH+VL, CDR-only, CrossAbSense, AbLang2, and ESM-2 inputs under cluster--isotype and random CV, respectively; colors identify assays and whiskers show sample SD across five folds. \textbf{C}, structural feature groups and PLM references; \textbf{D}, nine-encoder screen. C--D average the same five assays within each fold, then show the mean $\pm$ SD of those five fold means; SD across assays is not used as uncertainty of the mean. \textbf{E}, four encoder-only GDPa3 means with joint antibody-bootstrap percentile 95\% CIs (2,000 paired resamples across the five assays). \textbf{F}, the single retained heatmap shows per-assay CV mean $\pm$ fold SD for five structural groups. Combined features reach HIC $\rho\simeq.66$, whereas Tm2 remains weak. All panels use HIC, Tm2, AC-SINS, PR-CHO, and Titer, rather than the primary positive-signal five-assay set. These are standalone representation screens.')
caption('main05_efficiency.pdf',r'\textbf{Source ablation, data efficiency, matched held-out differences, and a regional diagnostic.} \textbf{A}, primary-code full-minus-source-removed GDPa3 $\Delta\rho$. \textbf{B}, cluster--isotype learning curves with $\pm$ SD across five outer folds. \textbf{C}, paired primary-minus-PLM differences with BCa 95\% CIs (2,000 antibody resamples; exploratory, no multiplicity adjustment). A--C retain the competition-five assay axes; Tm2 and Titer use the unchanged code defaults. Primary comparisons on HIC, SMAC, and HAC support improvement over both PLMs; see Table~\ref{tab:paired}. \textbf{D}, fixed CDR-enrichment summaries from a separate chain-aware network, with its CDR-length reference; these are not uncertainty intervals or direct attributions of the primary ensemble.')
caption('si01_detailed_shap.pdf',r'\textbf{Conditional proxy SHAP importance, historical coefficients, and individual contributions.} \textbf{A--C}, refitted 165-descriptor LightGBM models for HIC, Tm2, and AC-SINS, explained using path-dependent TreeSHAP. Bars show the top-12 mean absolute contributions and antibody-bootstrap percentile 95\% CIs (2,000 resamples), conditional on each fitted proxy. \textbf{D}, the fixed historical six-head source-stack coefficient matrix; fitted coefficients are not replicate means and have no error bars. \textbf{E}, individual-antibody signed category contributions from the separately stored expanded physicochemical proxies. Each stacked column is one antibody, rather than a sampling mean. Neither proxy analysis is a direct attribution of the four-expert primary model.')
caption('si02_soft_moe_extensions.pdf',r'\textbf{Source-gating and physics diagnostics, and bispecific arm-average transfer.} \textbf{A}, concatenated Ridge, soft source gate, and best-block reference, with BCa 95\% intervals of pooled random-fold OOF correlations. These source scripts use shuffled KFold, not the primary cluster--isotype protocol, and the source gate reuses base OOF predictions; the results are exploratory diagnostics. \textbf{B}, mean source-gate weights with conditional antibody-bootstrap 95\% intervals. \textbf{C--E}, isotonic SAP, rank regularization, and shared-PCA diagnostics, with conditional OOF BCa intervals; shared PCA was fitted globally in that historical script and is not a leakage-controlled primary-model test. \textbf{F--H}, bispecific observed-versus-arm-average predictions, with correlation CIs annotated in the plots. Correctly paired antibody bootstraps replace invalid stored interval records. Shared parental antibodies remain a limitation; these CIs are not parent-independent or prospective transfer evidence. All intervals use 2,000 resamples. No error bars are assigned to individual antibody scatter points.')
caption('main_headline_unique.pdf',r'\textbf{Primary aggregate result and full assay scope with uncertainty.} \textbf{A}, the matched nine-strategy comparison across HIC, AC-SINS, PR-CHO, SMAC, and HAC. AbDev-X has the largest mean point estimate, $.472$; whiskers are joint antibody-bootstrap percentile 95\% CIs, preserving dependence across assays and respecting missing labels. The primary mean CI is $[.349,.576]$. \textbf{B}, all ten assay-level correlations with BCa 95\% CIs. Blue marks the five primary-comparison endpoints and grey the five code-default outputs. These descriptive assay groups do not define a prospectively registered successful subset. Intervals concern correlations, not individual predictions.')
caption('si03_expert_specialization_unique.pdf',r'\textbf{Selection stability and expert-internal refit variability.} \textbf{A}, source-selection fractions from the recorded 2,000-resample study, with Wilson intervals describing Monte Carlo uncertainty in the estimated bootstrap frequencies; these are not predictive CIs. \textbf{B--C}, D-Stack signed stream coefficients and F-MoE mechanistic-group weights, shown as means $\pm$ sample SD across five outer-training-partition refits. These refit summaries are distinct from the fixed full-training coefficients. Ineligible F-MoE groups are omitted. The final four-expert weights remain fixed at $.25$ and are not antibody-dependent gates.')
caption('si04_routing_architecture_unique.pdf',r'\textbf{Architecture, routing, and pooling comparisons.} \textbf{A}, historical architecture means $\pm$ SD, calculated by averaging the five assay scores within each held-out fold before taking the SD across folds. \textbf{B--C}, archived routing and hybrid-model points; open symbols indicate that uncertainty is not recoverable from the retained records (NR). No intervals are inferred from differences between models or assays. \textbf{D}, the original no-PCA ESM-2 pooling experiment, reproduced with $\pm$ fold SD for mean, CDR, and framework pooling. It differs from the PCA-based input screen in the main figure. These source configurations do not replace the primary ensemble evaluation.')
caption('si05_transfer_ranking_unique.pdf',r'\textbf{Transfer and composite-ranking analyses.} \textbf{A}, paired-antibody BCa 95\% CIs for the four historical VHH-Fc prediction strategies. \textbf{B}, GDPa1-only versus combined-format training; filled points have recovered prediction records and BCa intervals, whereas open points have unavailable uncertainty (NR). \textbf{C}, archived composite precision at $K=5,10,20$; model-prediction uncertainty is NR, and the random reference is a theoretical expectation. These configurations are separate from the current four-expert model. Bispecific transfer is shown in Figure~\ref{fig:soft_extensions}F--H.')
caption('si06_augmentation_confidence_unique.pdf',r'\textbf{Augmentation, perturbation, and confidence diagnostics.} \textbf{A}, stored augmentation results with their recorded antibody-bootstrap 95\% intervals. \textbf{B}, HIC means $\pm$ SD across repeated numerical feature perturbations; a zero perturbation SD at $\sigma=0$ denotes a deterministic calculation, not zero prediction uncertainty. \textbf{C}, archived disagreement--error correlations; uncertainty is NR. \textbf{D}, retained-set correlations with the source paired-antibody bootstrap 95\% intervals after abstention. These studies retain their historical source-stack identities and do not establish calibrated individual uncertainty for AbDev-X.')
caption('si07_learner_screen_unique.pdf',r'\textbf{Additional learners and regional descriptors.} \textbf{A}, recorded Ridge, XGBoost, and TabPFN means for five feature configurations; the retained table contains single points without prediction records or run-level uncertainty (NR, open symbols). \textbf{B}, reproduced regional descriptor models with BCa 95\% CIs from 2,000 paired GDPa3 antibody resamples. These are descriptor constructions, not newly trained hierarchical neural networks; several constructions select equivalent columns and consequently give overlapping results. All B panels use the five primary-comparison assays.')
